53	  // to return an int and take an int parameter.
54	  FunctionType *FibFTy = FunctionType::get(Type::getInt32Ty(Context),
55	                                           {Type::getInt32Ty(Context)}, false);
56	  Function *FibF =
57	      Function::Create(FibFTy, Function::ExternalLinkage, "fib", M);
