91	/// This provides a helper for copying FMF from an instruction or setting
92	/// specified flags.
93	class FMFSource {
94	  std::optional<FastMathFlags> FMF;
95	
96	public:
97	  FMFSource() = default;
98	  FMFSource(Instruction *Source) {
99	    if (Source)
100	      FMF = Source->getFastMathFlags();
101	  }
